        pointer-events: none;
      }

      /* Hide Scrollbar for Slider */
      .scrollbar-none::-webkit-scrollbar {
        display: none !important;
        width: 0 !important;
        height: 0 !important;
        background: transparent !important;
      }

      .scrollbar-none {
        -ms-overflow-style: none !important;
        scrollbar-width: none !important;
        overflow-y: hidden !important;
      }

      /* Cert Card Style */
      .cert-card {
        background: #ffffff;
        border: 1px solid #e8edea;
        border-radius: 18px;
        padding: 14px 20px;
        display: flex;
        align-items: center;
        justify-content: center;
        height: 96px;
        min-width: 195px;
        max-width: 250px;
        flex-shrink: 0;
        transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
        position: relative;
        cursor: pointer;
        box-shadow: 0 2px 10px rgba(11, 31, 22, 0.03);
      }

      .cert-card:hover {
        border-color: #1F6B43;
        transform: translateY(-3px);
        box-shadow: 0 10px 20px -5px rgba(31, 107, 67, 0.12);
      }

      .cert-card-img {
        max-height: 100%;
        max-width: 100%;
        object-fit: contain;
        transition: transform 0.2s ease;
      }

      .cert-card:hover .cert-card-img {
        transform: scale(1.05);
      }

      /* Thumbnail Cert Card */
      .cert-thumb-card {
        background: #ffffff;
        border: 1.5px solid #e8edea;
        border-radius: 16px;
        padding: 6px;
        height: 118px;
        min-width: 165px;
        flex-shrink: 0;
        transition: all 0.25s ease;
        cursor: pointer;
        position: relative;
        overflow: hidden;
      }

      .cert-thumb-card:hover {
        border-color: #1F6B43;
        box-shadow: 0 12px 24px -6px rgba(31, 107, 67, 0.15);
        transform: translateY(-3px);
      }

      /* Quality policy: hold the statement to two lines on laptops too.
         The English copy needs ~1195px per line at the inherited 23.125px, but the
         card only offers ~1115px at a 1280px viewport, so it spilled to three lines
         there. One step down in size covers 1250-1400px; the band starts at 1250
         rather than 1200 because at 1200 the card is down to 1035px and even 20.5px
         does not fit two lines. Below that, two lines would need type under 19px,
         which is worse than simply wrapping, so the copy wraps naturally there.
         !important is required: components/style.css sets
         `[class*="text-lg"]{font-size:1.25rem!important}` and the paragraph carries
         sm:text-lg. */
      @media (min-width: 1250px) and (max-width: 1399.98px) {
        #quality-policy-statement {
          font-size: 20.5px !important;
          line-height: 1.62 !important;
        }
      }
    </style>
