    <!-- ==========================================
         JAVASCRIPT CONTROLLERS (Smooth 60fps Infinite Marquee Ticker)
    ========================================== -->
    <script>
      // Toggle detailed categorized certification rows
      function toggleCertDetail(btn) {
        var d = document.getElementById('certifications-detail');
        if (!d) return;
        var isHidden = d.classList.toggle('hidden');
        btn.querySelectorAll('.cert-toggle-label.lang-th')[0].textContent = isHidden ? 'ดูใบรับรองทั้งหมด' : 'ซ่อนรายละเอียด';
        var en = btn.querySelector('.cert-toggle-label.lang-en'); if (en) en.textContent = isHidden ? 'View All Certifications' : 'Hide Details';
        var ic = btn.querySelector('.cert-toggle-icon'); if (ic) ic.style.transform = isHidden ? '' : 'rotate(90deg)';
        if (!isHidden) { setTimeout(function () { d.scrollIntoView({ behavior: 'smooth', block: 'start' }); }, 60); }
      }
      // Toggle extra items inside certification summary cards
      function toggleCardItems(btn) {
        var card = btn.closest('.rounded-2xl') || btn.parentElement;
        if (!card) return;
        var extraList = card.querySelector('.extra-items');
        if (!extraList) return;
        var isHidden = extraList.classList.toggle('hidden');
        var total = btn.getAttribute('data-total');
        var th = btn.querySelector('.lang-th');
        var en = btn.querySelector('.lang-en');
        var icon = btn.querySelector('i');
        if (th) th.textContent = isHidden ? 'ดูทั้งหมด (' + total + ')' : 'ย่อลง';
        if (en) en.textContent = isHidden ? 'View All (' + total + ')' : 'Show Less';
        if (icon) icon.className = isHidden ? 'fa-solid fa-chevron-down text-[10px] transition-transform duration-300' : 'fa-solid fa-chevron-up text-[10px] transition-transform duration-300';
      }
      window.toggleCardItems = toggleCardItems;
      window.toggleCertDetail = toggleCertDetail;

      // Seamless Continuous Infinite Marquee Ticker (60fps, No Jumps/Stutter)
      document.querySelectorAll('[id^="slider-row-"]').forEach((row, idx) => {
        row.style.cursor = 'grab';
        row.style.userSelect = 'none';
        row.style.scrollBehavior = 'auto'; // Disable native smooth scroll during RAF updates to prevent jump glitches

        // Duplicate content to 3 sets to guarantee endless seamless wrapping
        if (row.children.length > 0) {
          const originalContent = row.innerHTML;
          row.innerHTML = originalContent + originalContent + originalContent;
        }

        let isInteracting = false;
        let interactionTimeout = null;

        // Different smooth subpixel speeds per row (0.6px to 0.85px per frame @ 60fps)
        const speeds = [0.75, 0.6, 0.85, 0.65];
        const speed = speeds[idx % speeds.length];

        const markInteraction = (delay = 1500) => {
          isInteracting = true;
          if (interactionTimeout) clearTimeout(interactionTimeout);
          interactionTimeout = setTimeout(() => {
            isInteracting = false;
          }, delay);
        };

        // Track position as a float so sub-pixel speed accumulates even on
        // mobile browsers that round element.scrollLeft to integers.
        let pos = 0;
        function step() {
          if (!isInteracting) {
            const singleSetWidth = row.scrollWidth / 3;
            if (singleSetWidth > 0) {
              pos += speed;
              if (pos >= singleSetWidth * 2) pos -= singleSetWidth;
              else if (pos <= 0) pos += singleSetWidth;
              row.scrollLeft = pos;
            }
          }
          requestAnimationFrame(step);
        }

        // Start 60fps animation loop
        requestAnimationFrame(step);

        // Mouse & Touch interaction event handlers
        const parent = row.parentElement || row;
        parent.addEventListener('mouseenter', () => { isInteracting = true; });
        parent.addEventListener('mouseleave', () => { markInteraction(1000); });
        row.addEventListener('touchstart', () => { isInteracting = true; }, { passive: true });
        row.addEventListener('touchend', () => { pos = row.scrollLeft; markInteraction(1200); }, { passive: true });

        // Drag to scroll
        let down = false, moved = false, sx = 0, sl = 0;
        row.addEventListener('mousedown', (e) => {
          down = true; moved = false; isInteracting = true;
          sx = e.pageX; sl = row.scrollLeft;
          row.style.cursor = 'grabbing';
        });
        window.addEventListener('mouseup', () => {
          if (down) {
            down = false;
            row.style.cursor = 'grab';
            pos = row.scrollLeft;
            markInteraction(1500);
          }
        });
        window.addEventListener('mousemove', (e) => {
          if (!down) return;
          const dx = e.pageX - sx;
          if (Math.abs(dx) > 5) moved = true;
          row.scrollLeft = sl - dx;
        });
        row.addEventListener('click', (e) => {
          if (moved) { e.stopPropagation(); e.preventDefault(); moved = false; }
        }, true);
      });

      function scrollRow(rowId, offset) {
        const container = document.getElementById(rowId);
        if (container) {
          container.scrollBy({ left: offset, behavior: 'smooth' });
        }
      }

      // Open Lightbox Modal Preview
      function openCertModal(title, description, imgPath) {
        document.getElementById('modalTitle').innerText = title;
        document.getElementById('modalDesc').innerText = description;
        document.getElementById('modalImg').src = imgPath;

        const modal = document.getElementById('certModal');
        modal.classList.remove('hidden');
        modal.classList.add('flex');
      }

      // Close Modal
      function closeCertModal() {
        const modal = document.getElementById('certModal');
        modal.classList.add('hidden');
        modal.classList.remove('flex');
      }

      // Close Modal on Overlay Click
      document.getElementById('certModal').addEventListener('click', function (e) {
        if (e.target === this) {
          closeCertModal();
        }
      });

    </script>

