    <script>
      // ===== BILINGUAL PLACEHOLDER SWITCHER =====
      (function () {
        function updatePlaceholders() {
          const lang = document.documentElement.getAttribute('lang') || 'th';
          document.querySelectorAll('[data-ph-th][data-ph-en]').forEach(function (el) {
            el.setAttribute('placeholder', lang === 'en' ? el.getAttribute('data-ph-en') : el.getAttribute('data-ph-th'));
          });
        }
        // Run on load
        updatePlaceholders();
        // Watch for lang attribute changes (triggered by language toggle)
        const observer = new MutationObserver(updatePlaceholders);
        observer.observe(document.documentElement, { attributes: true, attributeFilter: ['lang'] });
      })();
    </script>

